mapper.select:
SELECT dc.jsondata,db.rid_long,db.hid,db.doctorname FROM doctor_career dc INNER JOIN doctor_basic db ON dc.rid = db.rid WHERE 1=1 AND ( db.data_version_id = #{search_version_id} OR db.data_version_id_update = #{search_version_id} )
AND db.hid = #{search_hid}
AND dc.rid_long = #{search_rid_long}
ORDER BY db.createAt

SELECT db.deptname,db.specialties,db.rid_long,db.hid,db.doctorname FROM doctor_basic db WHERE 1=1 AND ( db.data_version_id = #{search_version_id} OR db.data_version_id_update = #{search_version_id} ) and db.standard_dpt IS NULL AND db.doctorname = '이길준'
AND db.hid = #{search_hid}
AND db.rid_long = #{search_rid_long}
ORDER BY db.createAt

SELECT db.specialties,db.rid_long,db.hid,db.doctorname,db.doctor_id FROM doctor_basic db WHERE 1=1 AND ( db.data_version_id = #{search_version_id} OR db.data_version_id_update = #{search_version_id} ) AND db.specialties IS NOT NULL AND db.doctor_id IS NOT NULL
AND db.hid = #{search_hid}
AND db.rid_long = #{search_rid_long}
ORDER BY db.createAt

SELECT dp.paper_id,dp.doctorName,dp.authors FROM doctor_paper dp INNER JOIN doctor_basic db ON dp.rid = db.rid WHERE 1=1 and dp.title IS NOT NULL and dp.pmid IS NOT NULL and authors IS NOT NULL
AND dp.data_version_id = #{search_version_id}
AND db.hid = #{search_hid}
ORDER BY dp.paper_id asc

SELECT dp.paper_id,dp.doctorName,dp.firstAuthors FROM doctor_paper dp INNER JOIN doctor_basic db ON dp.rid = db.rid WHERE 1=1 and dp.doctorName IS NOT NULL and dp.pmid IS NOT NULL and firstAuthors IS NOT NULL AND isFirstAuthor IS NULL
AND dp.data_version_id = #{search_version_id}
AND db.hid = #{search_hid}
ORDER BY dp.paper_id asc

SELECT a.rid, a.rid_long, a.deptname, a.hid,a.doctorname FROM doctor_basic a WHERE a.hid IN
#{item}
AND a.doctorname LIKE CONCAT(#{search_doctorname}, '%') LIMIT 10

SELECT dp.paper_id, dp.doctorName, dp.journalName, dp.impactFactor, dp.pmid, dp.quartile, dp.title_pubmed, dp.title as title_origin FROM doctor_paper dp INNER JOIN doctor_basic db ON dp.rid = db.rid WHERE 1=1 and dp.doctorName IS NOT NULL and dp.pmid IS NOT NULL and title_pubmed IS NOT NULL AND ( dp.quartile IS NULL OR dp.quartile = '' )
AND dp.data_version_id = #{search_version_id}
AND db.hid = #{search_hid}
ORDER BY dp.paper_id asc LIMIT 1

SELECT dp.journalName, db.hid, db.data_version_id, GROUP_CONCAT(dp.paper_id) as paper_ids FROM doctor_paper dp INNER JOIN doctor_basic db ON dp.rid = db.rid WHERE (dp.quartile IS NULL OR dp.quartile = '') AND (dp.journalName IS NOT NULL AND dp.journalName != '')
AND dp.data_version_id = #{search_version_id}
AND db.hid = #{search_hid}
GROUP BY dp.journalName, db.hid, db.data_version_id

mapper.update:
UPDATE doctor_paper dp INNER JOIN doctor_basic db ON dp.rid = db.rid SET dp.quartile = #{quartile}, dp.impactFactor = #{impactFactor}, dp.full_journalName = #{full_journalName}, dp.journal_issn = #{journal_issn}, dp.updateAt = now() WHERE dp.journalName = #{journalName}
AND dp.data_version_id = #{search_version_id}
AND db.hid = #{search_hid}
